26	class ResumeDriver
27	{
28	public:
29	  // data0/data1/abstractcs/command are defined once in abstract_command.hpp;
30	  // dmcontrol/dmstatus are run-control registers specific to this driver.
31	  static constexpr uint8_t kData0      = kDmiData0;
32	  static constexpr uint8_t kData1      = kDmiData1;
33	  static constexpr uint8_t kDmcontrol  = 0x10;
34	  static constexpr uint8_t kDmstatus   = 0x11;
35	  static constexpr uint8_t kAbstractcs = kDmiAbstractcs;
36	  static constexpr uint8_t kCommand    = kDmiCommand;
37	
38	  static constexpr uint16_t kCsrDpc      = 0x7B1;
39	  static constexpr uint16_t kCsrDcsr     = 0x7B0;
40	  static constexpr uint16_t kCsrPmpcfg0  = 0x3A0;
41	  static constexpr uint16_t kCsrPmpaddr0 = 0x3B0;
42	  static constexpr uint16_t kCsrFcsr     = 0x003;
43	  static constexpr uint16_t kCsrMstatus  = 0x300;
44	  static constexpr uint16_t kCsrMie      = 0x304;
45	  static constexpr uint16_t kCsrMtvec    = 0x305;
46	  static constexpr uint16_t kCsrMscratch = 0x340;
47	  static constexpr uint16_t kCsrMepc     = 0x341;
48	  static constexpr uint16_t kCsrMcause   = 0x342;
49	  static constexpr uint16_t kCsrMtval    = 0x343;
50	  static constexpr uint16_t kCsrMip      = 0x344;
51	  static constexpr uint16_t kCsrMcycle   = 0xB00;
52	  static constexpr uint16_t kCsrMinstret = 0xB02;
53	  // Andes machine setup CSRs crt0 writes at boot (see hybrid_state_v1):
54	  // mcache_ctl enables the L1 I/D caches, mmisc_ctl holds misc machine config.
55	  static constexpr uint16_t kCsrMcacheCtl = 0x7CA;
56	  static constexpr uint16_t kCsrMmiscCtl  = 0x7D0;
57	
58	  static constexpr uint32_t kDmcontrolDmactive  = 1u << 0;
59	  static constexpr uint32_t kDmcontrolResumereq = 1u << 30;
60	  static constexpr uint32_t kDmcontrolHaltreq   = 1u << 31;
61	
62	  static constexpr uint32_t kDmstatusAllhalted    = 1u << 9;
63	  static constexpr uint32_t kDmstatusAllresumeack = 1u << 17;
64	
65	  static constexpr uint32_t kAbstractcsBusy       = hybrid::kAbstractcsBusy;
66	  static constexpr uint32_t kAbstractcsCmderrMask = hybrid::kAbstractcsCmderrMask;
67	
68	  // mstatus extension-state fields: FS (bits 14:13), VS (bits 10:9).
69	  // "Initial" (01) is the minimal enable the abstract FPR / V writes require.
70	  static constexpr uint64_t kMstatusFsMask    = 0x6000ULL;
71	  static constexpr uint64_t kMstatusFsInitial = 0x2000ULL;
72	  static constexpr uint64_t kMstatusVsMask    = 0x600ULL;
73	  static constexpr uint64_t kMstatusVsInitial = 0x200ULL;
74	
75	  static constexpr unsigned kPollIterations = kDmiPollIterations;
76	
77	  explicit ResumeDriver(DmiBus& bus) : bus_{bus} {}
78	
79	  void resume(const hybrid_state_v1& state)
80	  {
81	    if (state.magic != HYBRID_STATE_MAGIC)
82	      throw std::runtime_error("ResumeDriver::resume: bad magic");
83	    if (state.version != HYBRID_STATE_VERSION)
84	      throw std::runtime_error("ResumeDriver::resume: unsupported version");
85	    // L6: only U(0)/S(1)/M(3) fit dcsr.prv; 2 is the reserved encoding.
86	    if (state.priv == 2 || state.priv > 3)
87	      throw std::runtime_error("ResumeDriver::resume: invalid privilege");
88	
89	    // dmactive must transition 0->1 in its own write before any other
90	    // DMCONTROL bit is honored (RISC-V Debug Spec).
91	    bus_.write(kDmcontrol, kDmcontrolDmactive);
92	    request_halt();
93	    poll_until_set(bus_, kDmstatus, kDmstatusAllhalted, "ResumeDriver halt");
94	
95	    // mstatus: enable FS / VS so the following FPR / V abstract writes are
96	    // accepted (FS or VS == Off disables the extension and the hart NACKs
97	    // the writes). The drained state.mstatus may legitimately carry FS or
98	    // VS at Off (e.g. an OS context-switched the regs away before the
99	    // trigger fired) -- gating the write on the drained field skips the
100	    // enable and silently NACKs every subsequent FPR / V-CSR write. Always
101	    // write mstatus when either extension is in scope; force-OR Initial
102	    // when the drained field is Off. This enable is local to the vsim
103	    // phase; the state.mstatus written to the handoff file is left
104	    // unmodified.
105	    if (state.flags & (HYBRID_FLAG_FP | HYBRID_FLAG_V)) {
106	      uint64_t enable_mstatus = state.mstatus;
107	      if ((state.flags & HYBRID_FLAG_FP) && (enable_mstatus & kMstatusFsMask) == 0)
108	        enable_mstatus |= kMstatusFsInitial;  // FS = Initial
109	      if ((state.flags & HYBRID_FLAG_V)  && (enable_mstatus & kMstatusVsMask) == 0)
110	        enable_mstatus |= kMstatusVsInitial;  // VS = Initial
111	      write_csr_abstract_or_pb(kCsrMstatus, enable_mstatus);
112	    }
113	
114	    // FPR restore (requires mstatus.FS enabled above): one abstract register
115	    // write per f-reg. Abstract-only by design, like every non-V register
116	    // block -- the Program Buffer is reserved for state the abstract command
117	    // space cannot reach (the V regfile, vtype/vl, L2C MMIO).
118	    if (state.flags & HYBRID_FLAG_FP) {
119	      for (uint16_t i = 0; i < 32; ++i)
120	        write_64bit_register(regno_fpr(i), state.fpr[i]);
121	      // L20: fcsr (frm + sticky fflags). Same FS gate as the FPRs; PB
122	      // fallback scratch x5 is overwritten by the GPR loop below.
123	      write_csr_abstract_or_pb(kCsrFcsr, state.fcsr);
124	    }
125	
126	    // L6: dret resumes into dcsr.prv, which is M after the boot halt. For an
127	    // S/U-mode handoff, read-modify-write the prv field so the ROI executes
128	    // in the drained privilege; M-mode states skip the write (prv already 3).
129	    // Before the GPR loop: a PB fallback would clobber scratch x5.
130	    if (state.priv != 3) {
131	      // L2 slice: with PMP implemented and no matching entry, every S/U
132	      // access faults (priv spec v1.10) -- mirror the producer's PMP block
133	      // so the ROI can fetch at all. All pmpaddr before any pmpcfg (a locked
134	      // cfg discards later addr writes); odd pmpcfg CSRs do not exist on
135	      // RV64. Tolerant writes: entries beyond what the hart implements
136	      // mirror as no-ops. M-mode handoffs keep PMP pass-through-only (L2).
137	      for (uint16_t i = 0; i < HYBRID_PMP_ADDR_NUM; ++i)
138	        write_csr_tolerant(kCsrPmpaddr0 + i, state.pmpaddr[i]);
139	      for (uint16_t i = 0; i < HYBRID_PMP_CFG_NUM; i += 2)
140	        write_csr_tolerant(kCsrPmpcfg0 + i, state.pmpcfg[i]);
141	
142	      const uint64_t dcsr =
143	        read_register_64(bus_, regno_csr(kCsrDcsr), "ResumeDriver dcsr");
144	      write_csr_abstract_or_pb(kCsrDcsr,
145	                               (dcsr & ~uint64_t{0x3}) | state.priv);
146	      // An M-only core WARL-pins dcsr.prv to 3; resuming anyway would
147	      // silently measure the ROI in the wrong privilege. Verify and abort.
148	      const uint64_t got =
149	        read_register_64(bus_, regno_csr(kCsrDcsr), "ResumeDriver dcsr verify")
150	        & 0x3u;
151	      if (got != state.priv)
152	        throw std::runtime_error(
153	          "ResumeDriver::resume: engine does not implement privilege level "
154	          + std::to_string(state.priv)
155	          + " (dcsr.prv pinned to " + std::to_string(got)
156	          + "); pick an S/U-capable engine");
157	    }
158	
159	    // GPRs x1..x31 + DPC: one abstract register write each (DATA0/DATA1 +
160	    // Access-Register COMMAND), abstract-only by design. x0 is hardwired zero
161	    // and is skipped. M-mode CSRs, PMP and V land in later commits; M-mode
162	    // CSRs/PMP are pass-through-merged at drain time, never programmed through
163	    // a DM abstract command here.
164	    for (uint16_t i = 1; i < 32; ++i)
165	      write_64bit_register(regno_gpr(i), state.gpr[i]);
166	    write_64bit_register(regno_csr(kCsrDpc), state.pc);
167	
168	    write_csr_tolerant(kCsrMtvec, state.mtvec);
169	
170	    // L23: mscratch is the M-mode software scratch CSR -- a pure read/write
171	    // register with no hardware side effects, legal to use inside a trap-free
172	    // ROI. Restore it so a value stashed before the handoff survives into the
173	    // vsim phase.
174	    write_csr_tolerant(kCsrMscratch, state.mscratch);
175	
176	    // L24: the writable M-mode trap/interrupt CSRs. In the trap-free,
177	    // interrupt-free ROI envelope these are ordinary read/write registers, so a
178	    // value stashed before the handoff must survive into the vsim phase (same
179	    // round-trip as mscratch). Tolerant writes: a WARL / read-only field (mip's
180	    // hardware-driven pending bits, or mtval on a core that hardwires it)
181	    // mirrors as a no-op. medeleg/mideleg/satp stay unrestored -- they are
182	    // S-mode CSRs the M-only default engine does not implement (L3/L4).
183	    write_csr_tolerant(kCsrMepc,   state.mepc);
184	    write_csr_tolerant(kCsrMcause, state.mcause);
185	    write_csr_tolerant(kCsrMtval,  state.mtval);
186	    write_csr_tolerant(kCsrMie,    state.mie);
187	    write_csr_tolerant(kCsrMip,    state.mip);
188	
189	    // Andes cache fix: restore the machine setup CSRs crt0 wrote at boot. The
190	    // functional engine ran crt0 (where `csrw mcache_ctl` enables the L1 I/D
191	    // caches) but has no cache model, so without this the cycle engine resumes
192	    // at the ROI with caches at their reset default -- DISABLED -- and the
193	    // whole measured window runs uncached, inflating it severalfold. Tolerant
194	    // writes: an engine without these custom CSRs (e.g. non-Andes) mirrors the
195	    // write as a no-op, and a drained 0 (caches were off) restores the reset
196	    // state, so this is always safe to issue.
197	    write_csr_tolerant(kCsrMcacheCtl, state.mcache_ctl);
198	    write_csr_tolerant(kCsrMmiscCtl,  state.mmisc_ctl);
199	
200	    // F-T2.4: restore mcycle/minstret so the vsim phase continues counting
201	    // from QEMU1's drain value. Without this, vsim's local counter starts
202	    // at zero, so the drained mcycle delta (vsim minus QEMU 1) would no
203	    // longer measure the ROI. PB fallback uses x5 as scratch; safe to
204	    // overwrite here as the GPR loop already ran.
205	    write_csr_abstract_or_pb(kCsrMcycle,   state.mcycle);
206	    write_csr_abstract_or_pb(kCsrMinstret, state.minstret);
207	
208	    clear_cmderr_if_set();
209	    request_resume();
210	    poll_until_set(bus_, kDmstatus, kDmstatusAllresumeack,
211	                   "ResumeDriver resume");
212	  }
213	
214	private:
215	  void request_halt()
216	  {
217	    bus_.write(kDmcontrol, kDmcontrolDmactive | kDmcontrolHaltreq);
218	  }
219	
220	  void request_resume()
221	  {
222	    bus_.write(kDmcontrol, kDmcontrolDmactive | kDmcontrolResumereq);
223	  }
224	
225	  void write_64bit_register(uint16_t regno, uint64_t value)
226	  {
227	    write_register_abstract(bus_, regno, value);
228	  }
229	
230	  // Abstract-first CSR write with Program Buffer fallback.
231	  // Tries an abstract register write; if the DM signals cmderr, clears it,
232	  // stages the value in scratch_gpr via abstract GPR write, then executes a
233	  // one-instruction PB (`csrrw x0, csr, scratch_gpr`).  scratch_gpr defaults
234	  // to x5 (t0) which the GPR restore loop overwrites later.
235	  void write_csr_abstract_or_pb(uint16_t csr, uint64_t value,
236	                                 uint8_t scratch_gpr = 5)
237	  {
238	    write_64bit_register(regno_csr(csr), value);
239	    if ((bus_.read(kAbstractcs) & kAbstractcsCmderrMask) == 0u) return;
240	    bus_.write(kAbstractcs, kAbstractcsCmderrMask);  // W1C: clear sticky error
241	    write_64bit_register(regno_gpr(scratch_gpr), value);
242	    const std::array<uint32_t, 1> pb = { encode_csrrw(0, csr, scratch_gpr) };
243	    exec_progbuf(bus_, std::span<const uint32_t>{pb});
244	  }
245	
246	  // Write a CSR-addressable register and clear any cmderr the DM raised.
247	  // Used for CSRs whose abstract-access support may be implementation
248	  // dependent; a missing CSR mirrors as a no-op rather than blocking the
249	  // remaining writes.
250	  void write_csr_tolerant(uint16_t csr, uint64_t value)
251	  {
252	    write_64bit_register(regno_csr(csr), value);
253	    clear_cmderr_if_set();
254	  }
255	
256	  // abstractcs.cmderr is sticky per the Debug Spec - a subsequent command
257	  // is rejected until the bits are W1C-cleared. We tolerate per-register
258	  // failures (e.g. unimplemented FPR/CSR Abstract access) by clearing the
259	  // error before resuming so the hart isn't left in a stuck state.
260	  // B17: record the last observed non-zero cmderr and a clear count so a
261	  // partially-broken restore is observable via the public accessors
262	  // instead of silently swallowed.
263	  void clear_cmderr_if_set()
264	  {
265	    const auto status = bus_.read(kAbstractcs);
266	    const auto code = (status & kAbstractcsCmderrMask) >> 8;
267	    if (code != 0u) {
268	      last_observed_cmderr_ = code;
269	      ++cmderr_clear_count_;
270	      bus_.write(kAbstractcs, kAbstractcsCmderrMask);
271	    }
272	  }
273	
274	  DmiBus& bus_;
275	  uint32_t last_observed_cmderr_ = 0;
276	  uint64_t cmderr_clear_count_   = 0;
277	
278	public:
279	  // B17: diagnostic side channel. Non-zero last_observed_cmderr() means
280	  // at least one abstract write tripped a sticky cmderr the restore
281	  // tolerated by clearing. cmderr_clear_count() is the total number of
282	  // such clears across all calls into clear_cmderr_if_set() this run.
283	  auto last_observed_cmderr() const -> uint32_t { return last_observed_cmderr_; }
284	  auto cmderr_clear_count() const -> uint64_t   { return cmderr_clear_count_; }
285	};
286	
287	// Read a 64-bit hart register (GPR / FPR / CSR by abstract regno) over DMI
288	// via an Abstract Command. Halts-and-reads contract: caller must have the
289	// hart in the halted state. Shared with StateDrain (drain at exit). If
290	// abstractcs.cmderr goes sticky after the command, the helper clears it and
291	// reports nullopt rather than blocking the caller -- a missing CSR mirrors as
292	// absent instead of corrupting the adjacent field.
293	inline auto read_register_64_checked(DmiBus& bus, uint16_t regno,
294	                                     const char* poll_label
295	                                       = "read_register_64")
296	  -> std::optional<uint64_t>
297	{
298	  using RD = ResumeDriver;
299	  bus.write(RD::kCommand,
300	            access_register_command(regno, AarSize::Bits64, /*write=*/false));
301	  poll_until_clear(bus, RD::kAbstractcs, RD::kAbstractcsBusy, poll_label);
302	  const auto status = bus.read(RD::kAbstractcs);
303	  if ((status & RD::kAbstractcsCmderrMask) != 0u) {
304	    bus.write(RD::kAbstractcs, RD::kAbstractcsCmderrMask);
305	    return std::nullopt;
306	  }
307	  const uint64_t lo = bus.read(RD::kData0);
308	  const uint64_t hi = bus.read(RD::kData1);
309	  return lo | (hi << 32);
310	}
311	
312	inline auto read_register_64(DmiBus& bus, uint16_t regno,
313	                             const char* poll_label = "read_register_64")
314	  -> uint64_t
315	{
316	  return read_register_64_checked(bus, regno, poll_label).value_or(0u);
317	}
