17	class StateDrain
18	{
19	public:
20	  using RD = ResumeDriver;
21	
22	  explicit StateDrain(DmiBus& bus) : bus_{bus} {}
23	
24	  // Drain x1..x31 + PC. FP/CSR/V slots remain zero; merge them in via
25	  // drain_with_passthrough when the QEMU 1 snapshot is available.
26	  auto drain() -> hybrid_state_v1
27	  {
28	    hybrid_state_v1 state{};
29	    state.magic   = HYBRID_STATE_MAGIC;
30	    state.version = HYBRID_STATE_VERSION;
31	    state.flags   = HYBRID_FLAG_RV64;
32	    halt_and_capture_pc_priv(state);
33	
34	    for (uint16_t i = 1; i < 32; ++i)
35	      state.gpr[i] = read_register_64(bus_, regno_gpr(i), "StateDrain GPR");
36	
37	    return state;
38	  }
39	
40	  // Returns the input snapshot with x1..x31 and PC overwritten by a fresh
41	  // DM read. When HYBRID_FLAG_FP is set, also freshly reads f0..f31 + fcsr
42	  // (L20) so post-vsim FP modifications are captured (otherwise the stale
43	  // QEMU 1 snapshot leaks into the drained state). L23 mscratch and the L24
44	  // trap/interrupt CSRs round-trip too (ResumeDriver restores them). The
45	  // Andes/M-ext, V and L2C re-reads land in later commits.
46	  // mcycle/minstret are always refreshed (F-T2.4): the vsim phase's
47	  // contribution would otherwise be discarded as the passthrough preserves
48	  // QEMU1's pre-handoff value.
49	  auto drain_with_passthrough(const hybrid_state_v1& input) -> hybrid_state_v1
50	  {
51	    auto state = input;
52	    halt_and_capture_pc_priv(state);  // L6: pc + privilege at the exit halt
53	
54	    // GPRs/FPRs: one abstract register read each. Abstract-only by design,
55	    // like the resume side -- the Program Buffer is reserved for state the
56	    // abstract command space cannot reach (the V regfile, vtype+vl, the L2C
57	    // MMIO window).
58	    for (uint16_t i = 1; i < 32; ++i)
59	      state.gpr[i] = read_register_64(bus_, regno_gpr(i), "StateDrain GPR");
60	
61	    if (input.flags & HYBRID_FLAG_FP) {
62	      for (uint16_t i = 0; i < 32; ++i)
63	        state.fpr[i] = read_register_64(bus_, regno_fpr(i), "StateDrain FPR");
64	      // L20: fcsr (frm + sticky fflags) accumulated by the vsim phase.
65	      state.fcsr = read_register_64(bus_, regno_csr(RD::kCsrFcsr));
66	    }
67	
68	    // L23: mscratch round-trips now (ResumeDriver restores it), so re-read it
69	    // from the hart -- otherwise an in-ROI write to the software scratch CSR is
70	    // dropped and the stale QEMU1 value passes through into the drained state.
71	    state.mscratch = read_register_64(bus_, regno_csr(RD::kCsrMscratch));
72	
73	    // L24: the writable M-mode trap/interrupt CSRs round-trip too (ResumeDriver
74	    // restores them), so re-read them -- an in-ROI write must reach the drained
75	    // state instead of the stale QEMU1 passthrough value.
76	    state.mepc   = read_register_64(bus_, regno_csr(RD::kCsrMepc));
77	    state.mcause = read_register_64(bus_, regno_csr(RD::kCsrMcause));
78	    state.mtval  = read_register_64(bus_, regno_csr(RD::kCsrMtval));
79	    state.mie    = read_register_64(bus_, regno_csr(RD::kCsrMie));
80	    state.mip    = read_register_64(bus_, regno_csr(RD::kCsrMip));
81	
82	    state.mcycle   = read_register_64(bus_, regno_csr(RD::kCsrMcycle));
83	    state.minstret = read_register_64(bus_, regno_csr(RD::kCsrMinstret));
84	
85	    return state;
86	  }
87	
88	private:
89	  // Halt the hart and capture the two control fields every drain path needs:
90	  // privilege (dcsr.prv, L6) and PC (dpc). dmactive must transition 0->1 in
91	  // its own write before haltreq is honored (RISC-V Debug Spec), then wait
92	  // for allhalted. Header fields and the register blocks are filled by the
93	  // caller.
94	  void halt_and_capture_pc_priv(hybrid_state_v1& state)
95	  {
96	    bus_.write(RD::kDmcontrol, RD::kDmcontrolDmactive);
97	    bus_.write(RD::kDmcontrol, RD::kDmcontrolDmactive | RD::kDmcontrolHaltreq);
98	    poll_until_set(bus_, RD::kDmstatus, RD::kDmstatusAllhalted,
99	                   "StateDrain halt");
100	
101	    state.priv = read_register_64(bus_, regno_csr(RD::kCsrDcsr),
102	                                  "StateDrain DCSR") & 0x3u;
103	    state.pc = read_register_64(bus_, regno_csr(RD::kCsrDpc), "StateDrain DPC");
104	  }
105	
106	  DmiBus& bus_;
107	};
