39	// DMI register addresses from RISC-V Debug Spec 1.0.
40	constexpr uint8_t kDmcontrol  = 0x10;
41	constexpr uint8_t kDmstatus   = 0x11;
42	constexpr uint8_t kAbstractcs = 0x16;
43	constexpr uint8_t kCommand    = 0x17;
44	constexpr uint8_t kData0      = 0x04;
45	constexpr uint8_t kData1      = 0x05;
46	
47	// CSR numbers from Debug Spec.
48	constexpr uint16_t kCsrDpc  = 0x7B1;
49	constexpr uint16_t kCsrDcsr = 0x7B0;
50	
51	struct DmiOp
52	{
53	  enum class Kind
54	  {
55	    Write,
56	    Read,
57	  };
58	  Kind kind;
59	  uint8_t reg;
60	  uint32_t value;  // for writes only
61	};
62	
63	struct RecordingBus final : hybrid::DmiBus
64	{
65	  std::vector<DmiOp> ops;
66	
67	  // bit 9: allhalted, bit 17: allresumeack. Answering both lets the poll
68	  // loops finish on their first read. abstractcs reads return 0 (busy clear,
69	  // no cmderr), so each abstract write completes immediately.
70	  uint32_t dmstatus_value = 0;
71	
72	  // When set, an abstract write-COMMAND to this CSR regno raises a sticky
73	  // cmderr (cleared only by the W1C abstractcs write the driver issues).
74	  // Models a hart that NACKs a particular abstract CSR access.
75	  std::optional<uint16_t> fail_csr_write;
76	
77	  // Mini register file: abstract write-COMMANDs latch the staged DATA0/DATA1
78	  // into regfile[regno]; abstract read-COMMANDs load it back so a read-modify-
79	  // write-verify sequence (dcsr.prv) observes its own writes. Regnos in
80	  // warl_ignore model WARL fields the hart pins (the write is recorded but
81	  // discarded), e.g. dcsr.prv on an M-only core.
82	  std::unordered_map<uint16_t, uint64_t> regfile;
83	  std::set<uint16_t> warl_ignore;
84	
85	  void write(uint8_t reg, uint32_t value) override
86	  {
87	    ops.push_back({DmiOp::Kind::Write, reg, value});
88	    if (reg == kData0) staged_data0_ = value;
89	    if (reg == kData1) staged_data1_ = value;
90	    if (reg == kAbstractcs && (value & kCmderrMask) != 0u)
91	      cmderr_sticky_ = false;  // W1C clear
92	    if (reg == kCommand && fail_csr_write) {
93	      const auto regno    = static_cast<uint16_t>(value & 0xffffu);
94	      const bool is_write = ((value >> 16) & 1u) != 0u;
95	      if (is_write && regno == hybrid::regno_csr(*fail_csr_write))
96	        cmderr_sticky_ = true;
97	    }
98	    if (reg == kCommand && value != hybrid::kExecProgbufCmd) {
99	      const auto regno    = static_cast<uint16_t>(value & 0xffffu);
100	      const bool is_write = ((value >> 16) & 1u) != 0u;
101	      if (is_write) {
102	        if (!warl_ignore.count(regno))
103	          regfile[regno] = (uint64_t{staged_data1_} << 32) | staged_data0_;
104	      } else {
105	        const auto it = regfile.find(regno);
106	        const uint64_t v = (it == regfile.end()) ? 0u : it->second;
107	        pending_data0_ = static_cast<uint32_t>(v);
108	        pending_data1_ = static_cast<uint32_t>(v >> 32);
109	      }
110	    }
111	  }
112	
113	  auto read(uint8_t reg) -> uint32_t override
114	  {
115	    ops.push_back({DmiOp::Kind::Read, reg, 0});
116	    if (reg == kDmstatus) return dmstatus_value;
117	    if (reg == kData0) return pending_data0_;
118	    if (reg == kData1) return pending_data1_;
119	    if (reg == kAbstractcs && cmderr_sticky_) return kCmderrMask;
120	    return 0;
121	  }
122	
123	private:
124	  static constexpr uint32_t kCmderrMask = 0x7u << 8;
125	  bool cmderr_sticky_ = false;
126	  uint32_t staged_data0_  = 0;
127	  uint32_t staged_data1_  = 0;
128	  uint32_t pending_data0_ = 0;
129	  uint32_t pending_data1_ = 0;
130	};
