132	auto rv64_state(uint64_t pc, uint64_t x1) -> hybrid_state_v1
133	{
134	  hybrid_state_v1 s{};
135	  s.magic = HYBRID_STATE_MAGIC;
136	  s.version = HYBRID_STATE_VERSION;
137	  s.flags = HYBRID_FLAG_RV64;
138	  s.pc = pc;
139	  s.priv = 3;
140	  s.gpr[1] = x1;
141	  return s;
142	}
143	
144	auto find_write(const std::vector<DmiOp>& ops, uint8_t reg)
145	  -> std::vector<uint32_t>
146	{
147	  std::vector<uint32_t> values;
148	  for (const auto& op : ops)
149	    if (op.kind == DmiOp::Kind::Write && op.reg == reg)
150	      values.push_back(op.value);
151	  return values;
152	}
