156	TEST_CASE("resume halts the hart before any abstract command")
157	{
158	  RecordingBus bus;
159	  bus.dmstatus_value = (1u << 9) | (1u << 17);
160	
161	  hybrid::ResumeDriver driver(bus);
162	  driver.resume(rv64_state(/*pc=*/0x80001000, /*x1=*/0xdeadbeef));
163	
164	  // The first write must prime dmactive (DM out of reset) BEFORE haltreq is
165	  // accepted; the second write must add haltreq while keeping dmactive set.
166	  REQUIRE(bus.ops.size() >= 2);
167	
168	  const auto& prime = bus.ops[0];
169	  CHECK(prime.kind == DmiOp::Kind::Write);
170	  CHECK(prime.reg == kDmcontrol);
171	  CHECK((prime.value & 1u) == 1u);                  // dmactive
172	  CHECK(((prime.value >> 31) & 1u) == 0u);          // haltreq NOT yet set
173	
174	  const auto& halt = bus.ops[1];
175	  CHECK(halt.kind == DmiOp::Kind::Write);
176	  CHECK(halt.reg == kDmcontrol);
177	  CHECK((halt.value & 1u) == 1u);                   // dmactive still set
178	  CHECK(((halt.value >> 31) & 1u) == 1u);           // haltreq
179	}
