181	TEST_CASE("resume programs x1..x31 via DATA0/DATA1 + COMMAND, skipping x0")
182	{
183	  RecordingBus bus;
184	  bus.dmstatus_value = (1u << 9) | (1u << 17);
185	
186	  auto s = rv64_state(0x80001000, 0xdeadbeef);
187	  for (int i = 0; i < 32; ++i) s.gpr[i] = 0xa00000000ULL + i;
188	
189	  hybrid::ResumeDriver driver(bus);
190	  driver.resume(s);
191	
192	  std::vector<uint32_t> cmds;
193	  for (const auto& op : bus.ops)
194	    if (op.kind == DmiOp::Kind::Write && op.reg == kCommand)
195	      cmds.push_back(op.value);
196	
197	  CHECK(cmds.size() >= 31);
198	
199	  // The first 31 COMMAND writes program x1..x31 in order, one abstract write
200	  // per register (the value rides the DATA0/DATA1 written just before each).
201	  for (int i = 1; i < 32; ++i) {
202	    const auto expect =
203	      hybrid::access_register_command(hybrid::regno_gpr(i),
204	                                      hybrid::AarSize::Bits64, /*write=*/true);
