312	
313	auto cmd_regnos(const std::vector<DmiOp>& ops) -> std::vector<uint16_t>
314	{
315	  std::vector<uint16_t> ns;
316	  for (const auto& op : ops)
317	    if (op.kind == DmiOp::Kind::Write && op.reg == kCommand)
318	      ns.push_back(static_cast<uint16_t>(op.value & 0xffffu));
319	  return ns;
320	}
321	
322	auto contains_regno(const std::vector<uint16_t>& ns, uint16_t regno) -> bool
323	{
324	  for (auto n : ns) if (n == regno) return true;
325	  return false;
326	}
