330	TEST_CASE("resume does NOT program M-mode CSRs/PMP via DM Abstract Commands; "
331	          "those fields are pass-through-merged at drain time instead")
332	{
333	  RecordingBus bus;
334	  bus.dmstatus_value = (1u << 9) | (1u << 17);
335	
336	  auto s = rv64_state(0x80001000, 0);
337	  s.mstatus = 0x1800ULL;
338	  for (int i = 0; i < HYBRID_PMP_CFG_NUM; ++i)  s.pmpcfg[i]  = 0xa0 + i;
339	  for (int i = 0; i < HYBRID_PMP_ADDR_NUM; ++i) s.pmpaddr[i] = 0xb0 + i;
340	
341	  hybrid::ResumeDriver driver(bus);
342	  driver.resume(s);
343	
344	  const auto ns = cmd_regnos(bus.ops);
345	  // mcycle(0xb00)/minstret(0xb02) are restored by resume (F-T2.4), mscratch
346	  // (0x340) since L23, and mepc(0x341)/mcause(0x342)/mtval(0x343)/mip(0x344)/
347	  // mie(0x304) since L24 -- none of those belong in this "must not program"
348	  // list. It now covers mstatus(0x300, restored only under FP/V; this state
349	  // has neither) plus the S-mode CSRs medeleg(0x302)/mideleg(0x303)/satp(0x180)
350	  // that the M-only default engine does not implement; those stay drain-time
351	  // pass-through.
352	  for (uint16_t csr : {0x300, 0x302, 0x303, 0x180})
353	    CHECK_FALSE(contains_regno(ns, hybrid::regno_csr(csr)));
354	  for (uint16_t i = 0; i < HYBRID_PMP_CFG_NUM; ++i)
355	    CHECK_FALSE(contains_regno(ns, hybrid::regno_csr(0x3a0 + i)));
356	}
