360	// COMMAND index of the first abstract write targeting regno, if any.
361	auto first_cmd_idx(const std::vector<DmiOp>& ops, uint16_t regno)
362	  -> std::optional<std::size_t>
363	{
364	  for (std::size_t i = 0; i < ops.size(); ++i) {
365	    const auto& op = ops[i];
366	    if (op.kind == DmiOp::Kind::Write && op.reg == kCommand
367	        && (op.value & 0xffffu) == regno)
368	      return i;
369	  }
370	  return std::nullopt;
371	}
