701	  // Force the mtvec abstract write to fail. mtvec goes through
702	  // write_csr_tolerant which intentionally does NOT take the PB fallback; it
703	  // just clears cmderr at the end. So the failure is only visible via the
704	  // side channel.
705	  bus.fail_csr_write = 0x305;  // CSR mtvec
706	
707	  hybrid::ResumeDriver driver(bus);
708	  driver.resume(rv64_state(0x80001000, 0));
709	
710	  CHECK(driver.cmderr_clear_count() > 0u);
711	  CHECK(driver.last_observed_cmderr() != 0u);
