namespace {

// True when `insn` appears in any Program-Buffer slot of the recorded ops.
auto pb_has_insn(const std::vector<DmiOp>& ops, uint32_t insn) -> bool
{
  for (const auto& op : ops)
    if (op.kind == DmiOp::Kind::Write
        && op.reg >= hybrid::kProgbuf0
        && op.reg <= hybrid::kProgbuf0 + hybrid::kProgbufMaxInsns
        && op.value == insn)
      return true;
  return false;
}

}  // namespace

TEST_CASE("resume with HYBRID_FLAG_V: PB reload sweeps v0 from scratch "
          "(minimal prototype)")
{
  RecordingBus bus;
  bus.dmstatus_value = (1u << 9) | (1u << 17);

  auto s = rv64_state(0x80001000, 0);
  s.flags |= HYBRID_FLAG_V;
  s.vlenb = 64;

  hybrid::ResumeDriver driver(bus, kScratch);
  driver.resume(s);

  // The minimal sweep runs a vsetvl (e8/m1) and a single vle8.v v0 from x7,
  // both via the Program Buffer.
  CHECK(pb_has_insn(bus.ops, hybrid::encode_vsetvl(0, 5, 6)));
  CHECK(pb_has_insn(bus.ops, hybrid::encode_vle8_v(0, 7)));

  // x7 is staged with the scratch base via a single abstract GPR write (its
  // value rides the DATA0/DATA1 written just before the COMMAND).
  bool x7_scratch = false;
  for (std::size_t i = 2; i < bus.ops.size(); ++i) {
    const auto& op = bus.ops[i];
    if (op.kind == DmiOp::Kind::Write && op.reg == kCommand
        && (op.value & 0xFFFFu) == hybrid::regno_gpr(7)
        && ((op.value >> 16) & 1u)) {
      const auto& d0 = bus.ops[i - 2];
      const auto& d1 = bus.ops[i - 1];
      if (d0.reg == kData0 && d0.value == uint32_t(kScratch & 0xFFFFFFFFu)
          && d1.reg == kData1 && d1.value == uint32_t(kScratch >> 32))
        x7_scratch = true;
    }
  }
  CHECK(x7_scratch);
}

TEST_CASE("resume without HYBRID_FLAG_V: no vsetvl PB instruction issued")
{
  RecordingBus bus;
  bus.dmstatus_value = (1u << 9) | (1u << 17);

  hybrid::ResumeDriver driver(bus, kScratch);
  driver.resume(rv64_state(0x80001000, 0));  // no HYBRID_FLAG_V

  CHECK_FALSE(pb_has_insn(bus.ops, hybrid::encode_vsetvl(0, 5, 6)));
}

